local ADDR_STEP_COUNT = 46185  -- USER_RAM5_U16
local ADDR_CRC16 = 46186  -- USER_RAM6_U16
local ADDR_CUR_STEP = 46187  -- USER_RAM7_U16
local ADDR_ERROR_CODE = 46188  -- USER_RAM8_U16
local ADDR_INTERP_VERSION = 46189  -- USER_RAM9_U16
local ADDR_ELAPSED_MS = 46100  -- USER_RAM0_U32
local ADDR_FIFO_DATA = 47000  -- USER_RAM_FIFO0_DATA_U16
local ADDR_FIFO_ALLOCATE = 47900  -- USER_RAM_FIFO0_ALLOCATE_NUM_BYTES
local ADDR_FIFO_BYTES_IN = 47910  -- USER_RAM_FIFO0_NUM_BYTES_IN_FIFO
local ADDR_FIFO_EMPTY = 47930  -- USER_RAM_FIFO0_EMPTY
local ADDR_DIO_STATE = 2800  -- DIO_STATE
